 auto range=[&](dx::Query& q,int choice){q.since=choice==11?0:now-seconds[std::clamp(choice,0,12)];q.until=INT64_MAX;if(choice==12){q.since=customSinceEpoch_>0?customSinceEpoch_:now;q.until=customUntilEpoch_>0?customUntilEpoch_:now;}};
 range(tableQuery_,tableTime_);range(mapQuery_,tableTime_);if(historyAll_){tableQuery_.since=std::max(tableQuery_.since,historyTableCleared_);mapQuery_.since=std::max(mapQuery_.since,historyMapCleared_);tableQuery_.firstSince=historyTableCleared_;mapQuery_.firstSince=historyMapCleared_;tableQuery_.afterRowId=mapQuery_.afterRowId=tableQuery_.firstAfterId=mapQuery_.firstAfterId=0;}else{tableQuery_.since=std::max(tableQuery_.since,tableCleared_);mapQuery_.since=std::max(mapQuery_.since,mapCleared_);tableQuery_.firstSince=tableCleared_;mapQuery_.firstSince=mapCleared_;}if(changed)engine_->query(tableQuery_,mapQuery_,++generation_);else engine_->refresh(tableQuery_,mapQuery_);lastRefresh_=ImGui::GetTime();
